//! # veil-crypto
//!
//! Security-critical primitives for Veil: identity and key-agreement keys,
//! authenticated encryption, key derivation, safety numbers, and QR payloads.
//!
//! Higher-level protocols (X3DH + Double Ratchet for 1:1, MLS for groups) live
//! in `veil-core` and build on these primitives.
//!
//! ## Scope and guarantees
//! * All random material comes from a caller-supplied CSPRNG.
//! * Secret keys are zeroized on drop where practical.
//! * AEAD nonces generated by this crate are random and non-repeating.
//!
//! ## Non-goals
//! This crate does not implement a wire protocol. Use [`veil-core`] for that.

#![forbid(unsafe_code)]
#![deny(missing_debug_implementations)]

pub mod aead;
pub mod error;
pub mod kdf;
pub mod keys;
pub mod qr;

pub use aead::{AeadKey, KEY_LEN, NONCE_LEN};
pub use error::{CryptoError, Result};
pub use keys::{safety_number, ExchangeKeyPair, IdentityKeyPair, IdentityPublicKey, PreKeyBundle};
pub use qr::{decode_prekey_bundle, encode_prekey_bundle, ADD_URI_PREFIX};

#[cfg(test)]
mod tests {
    use super::*;

    fn rng() -> rand::rngs::ThreadRng {
        rand::thread_rng()
    }

    #[test]
    fn sign_and_verify() {
        let mut r = rng();
        let id = IdentityKeyPair::generate(&mut r);
        let msg = b"hello veil";
        let sig = id.sign(msg);
        assert!(id.public().verify(msg, &sig).is_ok());
        assert!(id.public().verify(b"tampered", &sig).is_err());
    }

    #[test]
    fn safety_number_is_symmetric_and_60_digits() {
        let mut r = rng();
        let a = IdentityKeyPair::generate(&mut r).public();
        let b = IdentityKeyPair::generate(&mut r).public();
        let ab = safety_number(&a, &b);
        let ba = safety_number(&b, &a);
        assert_eq!(ab, ba);
        assert_eq!(ab.chars().filter(char::is_ascii_digit).count(), 60);
        assert_eq!(ab.split(' ').count(), 12);
    }

    #[test]
    fn aead_roundtrip_and_tamper_detection() {
        let mut r = rng();
        let key = AeadKey::generate(&mut r);
        let aad = b"header";
        let (ct, nonce) = key.encrypt_random(&mut r, aad, b"secret payload").unwrap();
        let pt = key.decrypt(&nonce, aad, &ct).unwrap();
        assert_eq!(pt, b"secret payload");

        let mut bad = ct.clone();
        bad[0] ^= 0x01;
        assert!(key.decrypt(&nonce, aad, &bad).is_err());
        assert!(key.decrypt(&nonce, b"wrong-aad", &ct).is_err());
    }

    #[test]
    fn kdf_is_deterministic() {
        let a = kdf::hkdf_sha256(b"ikm", b"salt", b"info", 32).unwrap();
        let b = kdf::hkdf_sha256(b"ikm", b"salt", b"info", 32).unwrap();
        assert_eq!(a, b);
        let c = kdf::hkdf_sha256(b"ikm", b"salt", b"other", 32).unwrap();
        assert_ne!(a, c);
    }

    #[test]
    fn qr_prekey_bundle_roundtrip() {
        let mut r = rng();
        let id = IdentityKeyPair::generate(&mut r);
        let ex = ExchangeKeyPair::generate(&mut r);
        let bundle = PreKeyBundle {
            identity_key: id.public().to_base64(),
            exchange_key: base64_encode(&ex.public().to_bytes()),
            signed_prekey: None,
            signed_prekey_signature: None,
        };
        let uri = encode_prekey_bundle(&bundle).unwrap();
        let parsed = decode_prekey_bundle(&uri).unwrap();
        assert_eq!(bundle, parsed);
    }

    fn base64_encode(bytes: &[u8]) -> String {
        use base64::Engine;
        base64::engine::general_purpose::STANDARD_NO_PAD.encode(bytes)
    }
}
